add_filter( 'login_redirect', 'perfectpixel_admin_login_landing_page', 20, 3 );

function perfectpixel_admin_login_landing_page( $redirect_to, $requested, $user ) {
	if ( ! $user instanceof WP_User || ! $user->has_cap( 'edit_products' ) ) {
		return $redirect_to;
	}
	// Only replace the default dashboard target.
	if ( $requested && untrailingslashit( $requested ) !== untrailingslashit( admin_url() ) ) {
		return $redirect_to;
	}
	return admin_url( ltrim( '{{admin_landing_path}}', '/' ) );
}
